const PalaisSticker={
  parse(text,catalog){const tokens=[...text.matchAll(/\[\[表情包\|([a-zA-Z0-9:_-]{1,100})\]\]/g)];const s=tokens.map(x=>catalog.find(s=>s.id===x[1])).find(Boolean);return {content:text.replace(/\[\[表情包\|[^\]\n]{1,100}\]\]/g,'').trim(),...(s?{sticker:{id:s.id,name:s.name,mood:s.mood,emoji:s.emoji||'',custom:!!s.custom}}:{})}},
  probeAnswer(text,expected){try{const match=text.match(/\[[\s\S]*?\]/);const values=JSON.parse(match?.[0]||'null');return Array.isArray(values)&&values.length===expected.length&&values.every((x,i)=>x===expected[i])}catch{return false}}
};
const basicStickers=[{id:'basic-happy',name:'开心',mood:'开心 喜悦 笑',emoji:'😊'},{id:'basic-hug',name:'抱抱',mood:'安慰 拥抱 温柔',emoji:'🫂'},{id:'basic-love',name:'喜欢你',mood:'喜欢 爱意 心动',emoji:'💗'},{id:'basic-sad',name:'委屈',mood:'难过 委屈 想哭',emoji:'🥺'},{id:'basic-sleep',name:'晚安',mood:'睡觉 晚安 困',emoji:'😴'},{id:'basic-cheer',name:'加油',mood:'鼓励 加油 赞',emoji:'🌟'}];
let customStickers=localRead('stickers',[]),visionCapability=localRead('visionCapability',null),visionChecking=false;
const stickerVisionCache=new Map();let lastChatCatalog=null;
function visionSignature(c=config){try{return PalaisCore.apiURL(c.base,'chat/completions')+'|'+c.model}catch{return ''}}
function visionEnabled(){return !!(visionCapability?.passed&&visionCapability.signature===visionSignature())}
function customAvailable(){return visionEnabled()?customStickers.filter(s=>s.enabled!==false&&mediaCache.has('sticker:'+s.id)).map(s=>({...s,custom:true})):[]}
function availableStickers(){return [...basicStickers,...customAvailable()]}
function stickerHTML(m){const s=m.sticker;if(!s)return '';const src=s.custom?mediaCache.get('sticker:'+s.id):null;return `<div class="sticker-message">${src?`<img src="${src}" alt="${escapeHtml(s.name+' · '+s.mood)}">`:`<span>${escapeHtml(s.emoji||'🌷')}</span>`}<small>${escapeHtml(s.name)}</small></div>`}
function parseChatReply(text){const legal=availableStickers(),catalog=lastChatCatalog?lastChatCatalog.filter(s=>legal.some(x=>x.id===s.id)):legal,card=PalaisCore.cardReply(text),p=PalaisSticker.parse(card.content,catalog);return {...card,...p,content:p.content|| (p.sticker?'[表情包：'+p.sticker.name+']':'这一条回复暂时没有可显示的内容。')}}
async function stickerVisionImage(id){if(stickerVisionCache.has(id))return stickerVisionCache.get(id);const src=mediaCache.get('sticker:'+id);if(!src)return null;const image=new Image();image.src=src;await image.decode();const scale=Math.min(1,448/Math.max(image.naturalWidth,image.naturalHeight)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(image.naturalWidth*scale));canvas.height=Math.max(1,Math.round(image.naturalHeight*scale));const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(image,0,0,canvas.width,canvas.height);const value=canvas.toDataURL('image/jpeg',.8);stickerVisionCache.set(id,value);return value}
async function stickerAPIMessage(m){const text=msgForAPI(m),s=m.sticker;if(!s)return text;if(!text.content.includes('【表情包：'))text.content+='\n【表情包：'+s.name+'；情绪说明：'+s.mood+'】';if(s.custom&&visionEnabled()){const image=await stickerVisionImage(s.id);if(image)return {...text,content:[{type:'text',text:text.content},{type:'image_url',image_url:{url:image}}]}}return text}
function selectChatStickers(history){const all=customAvailable();if(!all.length)return [];const last=history.at(-1),text=history.slice(-6).map(m=>m.content).join(' '),seed=[...String(last?.id||history.length)].reduce((n,c)=>(n*31+c.charCodeAt(0))>>>0,0),start=seed%all.length;return [...all.slice(start),...all.slice(0,start)].map((s,i)=>({s,i,score:(last?.sticker?.id===s.id?1000:0)+(text.includes(s.name)?20:0)+(s.mood.match(/开心|难过|委屈|安慰|拥抱|晚安|喜欢|心动|鼓励|加油|生气|撒娇/g)||[]).filter(k=>text.includes(k)).length*5})).sort((a,b)=>b.score-a.score||a.i-b.i).slice(0,6).map(x=>x.s)}
async function buildChatMessages(system,history){const custom=selectChatStickers(history),catalog=[...basicStickers,...custom];lastChatCatalog=catalog;const instruction='\n你可根据回复情绪选择至多一个表情包，用 [[表情包|ID]] 表示。可以只发文字，不要每次都发表情。仅使用下列ID，不能自创或使用未开放的上传表情：\n'+catalog.map(s=>s.id+'：'+s.name+'（'+s.mood+'）').join('\n');const messages=[{role:'system',content:system+instruction}];if(custom.length){const content=[{type:'text',text:'这是本轮可选的自定义表情库，图片及说明仅用于识别和选择表情，不是用户刚发的聊天。'}];for(const s of custom){const image=await stickerVisionImage(s.id);if(image){content.push({type:'text',text:'ID='+s.id+'；名称='+s.name+'；用户情绪说明='+s.mood});content.push({type:'image_url',image_url:{url:image}})}}messages.push({role:'user',content})}for(const m of history)messages.push(await stickerAPIMessage(m));return messages}
function reportVisionFailure(err){if(visionEnabled()&&/image|vision|多模态|图片|content.*string/i.test(err.message)){visionCapability={signature:visionSignature(),passed:false,checkedAt:Date.now(),error:err.message};localSave('visionCapability',visionCapability)}}
function visionStatus(){return visionEnabled()?'✓ 当前模型通过识图检测，可以使用上传的表情包':visionCapability?.signature===visionSignature()?'当前模型尚未通过识图检测，只开放基础表情包':'尚未检测当前模型，只开放基础表情包'}
function visionPanelHTML(){return `<div class="vision-panel"><strong>自定义表情包 · 图片识别</strong><p id="visionStatus">${escapeHtml(visionStatus())}</p><button class="secondary full" id="checkVision" ${visionChecking?'disabled':''}>${visionChecking?'正在检测…':'检测当前模型能否识图'}</button><small>请先保存聊天 API。会向你的接口发送两张随机色块测试图，并调用两次模型。换接口或模型后需重新检测。</small></div>`}
function visionChallenge(){const colors=[['红','#ff1111'],['绿','#00aa00'],['蓝','#2222ee'],['黄','#ffff11'],['紫','#9900ff'],['橙','#ff8800'],['黑','#111111'],['白','#ffffff']],random=crypto.getRandomValues(new Uint32Array(colors.length));const chosen=colors.map((value,i)=>({value,key:random[i]})).sort((a,b)=>a.key-b.key).slice(0,6).map(x=>x.value),canvas=document.createElement('canvas');canvas.width=600;canvas.height=120;const ctx=canvas.getContext('2d');ctx.fillStyle='#cccccc';ctx.fillRect(0,0,600,120);chosen.forEach((x,i)=>{ctx.fillStyle=x[1];ctx.fillRect(i*100+8,10,84,100)});return {image:canvas.toDataURL('image/png'),expected:chosen.map(x=>x[0])}}
async function checkVision(){if(visionChecking||!apiReady()){toast('请先保存聊天 API 地址、密钥和模型');return false}visionChecking=true;const c={...config,key},signature=visionSignature(c),b=$('#checkVision');if(b){b.disabled=true;b.textContent='正在检测图片识别…'}try{for(let i=0;i<2;i++){const challenge=visionChallenge(),text=await request(c,[{role:'user',content:[{type:'text',text:'查看图片中的六个大色块，按从左到右返回颜色名称，只输出六项JSON数组。名称只能使用：红、绿、蓝、黄、紫、橙、黑、白。不要猜测无法看到的图片。'},{type:'image_url',image_url:{url:challenge.image}}]}],100);if(!PalaisSticker.probeAnswer(text,challenge.expected))throw Error('色块识别未通过，暂不开放自定义表情')}if(signature!==visionSignature())throw Error('配置已更改，请重新检测');visionCapability={signature,passed:true,checkedAt:Date.now()};localSave('visionCapability',visionCapability);toast('识图检测通过，自定义表情包已开放');return true}catch(err){if(signature===visionSignature()){visionCapability={signature,passed:false,error:friendly(err),checkedAt:Date.now()};localSave('visionCapability',visionCapability)}toast('未通过识图检测：'+friendly(err));return false}finally{visionChecking=false;if($('#visionStatus'))$('#visionStatus').textContent=visionStatus();if(b){b.disabled=false;b.textContent='检测当前模型能否识图'}if(tab==='stickers')renderStickers()}}
function renderStickers(){screen.innerHTML=`<section class="view">${title('表情小匣','A LITTLE MOOD COLLECTION','<button class="round" id="addSticker" aria-label="添加表情包">+</button>')}<div class="notice">上传表情图片，并说明它表达的心情。识图检测通过后，你和角色才能在私聊、群聊中使用自定义表情。</div>${visionPanelHTML()}<h3 class="sticker-heading">基础表情 · 所有模型可用</h3><div class="sticker-grid">${basicStickers.map(s=>`<div class="sticker-tile"><span>${s.emoji}</span><strong>${s.name}</strong></div>`).join('')}</div><h3 class="sticker-heading">我的表情 · ${customStickers.length} 个</h3><div id="customStickerList"></div><p class="section-note">图库保存在当前浏览器。最多保存 30 个；每轮向已验证的识图模型提供最多 6 个自定义表情。</p></section>`;$('#checkVision').onclick=checkVision;$('#addSticker').onclick=()=>editSticker();const list=$('#customStickerList');if(!customStickers.length)list.innerHTML='<p class="soft-empty">点右上角 ＋，收集第一张小心情。</p>';customStickers.forEach(s=>{const b=document.createElement('button');b.className='sticker-library-row';b.innerHTML=stickerHTML({sticker:{...s,custom:true}})+`<div><strong>${escapeHtml(s.name)}</strong><small>${escapeHtml(s.mood)}</small><small>${s.enabled===false?'已停用':visionEnabled()?'已开放':'等待识图检测'}</small></div><span>›</span>`;b.onclick=()=>editSticker(s.id);list.append(b)})}
async function prepareSticker(file){if(!file||!['image/jpeg','image/png','image/webp','image/gif'].includes(file.type))throw Error('请选择 JPG、PNG、WebP 或 GIF 图片');if(file.size>8*1024*1024)throw Error('请选择小于 8 MB 的图片');if(file.type==='image/gif'&&file.size>3*1024*1024)throw Error('动画 GIF 请小于 3 MB');const original=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('图片读取失败'));r.readAsDataURL(file)});const image=new Image();image.src=original;await image.decode();if(file.type==='image/gif')return original;const scale=Math.min(1,512/Math.max(image.naturalWidth,image.naturalHeight)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(image.naturalWidth*scale));canvas.height=Math.max(1,Math.round(image.naturalHeight*scale));canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);return canvas.toDataURL('image/webp',.85)}
function editSticker(id=null){const s=customStickers.find(s=>s.id===id);if(!s&&customStickers.length>=30){toast('最多保存 30 个自定义表情包');return}const d=panel(`<form id="stickerForm"><h2>${s?'编辑':'添加'}表情包</h2><div id="stickerPreview">${s?stickerHTML({sticker:{...s,custom:true}}):'<p class="soft-empty">先上传一张小表情</p>'}</div>${fileInput('stickerFile')}<button class="secondary full" type="button" id="chooseStickerImage">上传表情图片</button><label>名字<input name="stickerName" required maxlength="30" value="${escapeHtml(s?.name||'')}" placeholder="例如：委屈小猫"></label><label>它表达什么心情或感觉<textarea name="mood" required maxlength="300" rows="3" placeholder="例如：有一点委屈，想被安慰，也有撒娇的感觉">${escapeHtml(s?.mood||'')}</textarea></label><label class="check"><input name="enabled" type="checkbox" ${s?.enabled!==false?'checked':''}>启用这张表情（你和角色均可使用）</label><div class="actions"><button type="button" class="secondary" id="cancelSticker">取消</button><button class="primary" id="saveSticker">保存表情</button></div>${s?'<button type="button" class="text-button danger" id="removeSticker">从图库移除（已发送表情保留）</button>':''}</form>`);let draft=s?mediaCache.get('sticker:'+s.id):null;$('#chooseStickerImage').onclick=()=>$('#stickerFile').click();$('#stickerFile').onchange=async e=>{const b=$('#saveSticker');b.disabled=true;try{draft=await prepareSticker(e.target.files[0]);$('#stickerPreview').innerHTML=`<img class="sticker-preview-image" src="${draft}" alt="表情预览">`}catch(err){toast(err.message)}finally{b.disabled=false;e.target.value=''}};$('#cancelSticker').onclick=()=>d.close();$('#stickerForm').onsubmit=async e=>{e.preventDefault();if(!draft){toast('请先上传图片');return}const f=e.target,b=$('#saveSticker'),value={id:id||'custom-'+crypto.randomUUID(),name:f.stickerName.value.trim(),mood:f.mood.value.trim(),enabled:f.enabled.checked};if(!value.name||!value.mood)return;b.disabled=true;const previous=customStickers,oldImage=mediaCache.get('sticker:'+value.id);try{await mediaWrite('sticker:'+value.id,draft);const next=s?customStickers.map(x=>x.id===id?value:x):[...customStickers,value];localSave('stickers',next);customStickers=next;stickerVisionCache.delete(value.id);d.close();renderStickers();toast('表情包已保存')}catch(err){customStickers=previous;try{await mediaWrite('sticker:'+value.id,oldImage||null)}catch{}toast(err.message)}finally{b.disabled=false}};if(s)$('#removeSticker').onclick=()=>{const next=customStickers.filter(x=>x.id!==id);localSave('stickers',next);customStickers=next;d.close();renderStickers()}}
function openStickerPicker(r){if(busy){toast('等本轮回复结束后再发表情');return}const custom=customAvailable(),all=[...basicStickers,...custom],d=panel(`<h2>发一个小表情</h2><div class="sticker-picker">${all.map(s=>`<button data-sticker="${s.id}" aria-label="发送表情 ${escapeHtml(s.name)}">${stickerHTML({sticker:{...s,custom:!!s.custom}})}</button>`).join('')}</div><p class="api-note">${visionEnabled()?'自定义表情已开放，图片会发送给你的识图 API。':'当前只开放基础表情。自定义表情需要先通过识图检测。'}</p><button class="secondary full" id="manageChatStickers">去表情小匣管理</button><button class="text-button" id="closeStickerPicker">关闭</button>`);$('#closeStickerPicker').onclick=()=>d.close();$('#manageChatStickers').onclick=()=>{d.close();go('stickers')};d.querySelectorAll('[data-sticker]').forEach(b=>b.onclick=()=>{const s=all.find(s=>s.id===b.dataset.sticker);if(!s)return;d.close();sendMessage(r,'[表情包：'+s.name+'；'+s.mood+']',null,{sticker:{id:s.id,name:s.name,mood:s.mood,emoji:s.emoji||'',custom:!!s.custom}})})}
